toolArgs.file_text:
@page "/book-appointment"
@rendermode InteractiveServer
@using sv_4e62db4787e34aa0b0e5d981aa3bfba6.Models
@using sv_4e62db4787e34aa0b0e5d981aa3bfba6.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

<EditForm Model="@_model" OnValidSubmit="HandleSubmitAsync" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* ───── STEP 1 ───── *@
    <fieldset class="mb-4">
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="_model.PatientName" />
            <ValidationMessage For="() => _model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="_model.Email" />
            <ValidationMessage For="() => _model.Email" />
            @if (_serverErrors.ContainsKey(nameof(_model.Email)))
            {
                <div class="validation-message">@_serverErrors[nameof(_model.Email)]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="_model.Phone" />
            <ValidationMessage For="() => _model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="_model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => _model.InsuranceProvider" />
        </div>

        @if (!_showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2Async">
                Next
            </button>
        }
    </fieldset>

    @* ───── STEP 2 ───── *@
    @if (_showStep2)
    {
        <fieldset class="mb-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select"
                             @bind-Value="_model.PreferredDoctor"
                             @bind-Value:after="OnDoctorChangedAsync">
                    <option value="">-- Select --</option>
                    @foreach (var doc in _doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => _model.PreferredDoctor" />
                @if (_serverErrors.ContainsKey(nameof(_model.PreferredDoctor)))
                {
                    <div class="validation-message">@_serverErrors[nameof(_model.PreferredDoctor)]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control"
                           @bind-Value="_model.AppointmentDate"
                           @bind-Value:after="OnDateChangedAsync"
                           min="@DateOnly.FromDateTime(DateTime.Today.AddDays(1)).ToString("yyyy-MM-dd")" />
                <ValidationMessage For="() => _model.AppointmentDate" />
                @if (_dateInPastError)
                {
                    <div class="validation-message">Date must be in the future.</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeslot">Time Slot</label>
                <InputSelect id="timeslot" class="form-select" @bind-Value="_model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in _timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => _model.TimeSlot" />
                @if (_serverErrors.ContainsKey(nameof(_model.TimeSlot)))
                {
                    <div class="validation-message">@_serverErrors[nameof(_model.TimeSlot)]</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="_model.ReasonForVisit" />
                <ValidationMessage For="() => _model.ReasonForVisit" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-outline-secondary" @onclick="GoBackToStep1">
                    Back
                </button>
                <button type="button" class="btn btn-info" @onclick="CheckAvailabilityAsync">
                    Check Availability
                </button>
                <button type="submit" class="btn btn-success" disabled="@(!_availabilityChecked)">
                    Book Appointment
                </button>
            </div>
        </fieldset>
    }
</EditForm>

@if (_submitted)
{
    <div class="alert alert-success mt-3">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentFormModel _model = new();
    private List<string> _doctors = [];
    private List<string> _timeSlots = [];
    private Dictionary<string, string> _serverErrors = new();

    private bool _showStep2;
    private bool _dateInPastError;
    private bool _availabilityChecked;
    private bool _submitted;

    private EditContext? _editContext;

    protected override async Task OnInitializedAsync()
    {
        _editContext = new EditContext(_model);
        _doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2Async()
    {
        _editContext = new EditContext(_model);
        var isValid =
            !string.IsNullOrWhiteSpace(_model.PatientName) &&
            !string.IsNullOrWhiteSpace(_model.Email) &&
            new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(_model.Email) &&
            !string.IsNullOrWhiteSpace(_model.Phone) &&
            !string.IsNullOrWhiteSpace(_model.InsuranceProvider);

        if (isValid)
        {
            _showStep2 = true;
        }
    }

    private void GoBackToStep1()
    {
        _showStep2 = false;
        _availabilityChecked = false;
        _serverErrors.Clear();
    }

    private async Task OnDoctorChangedAsync()
    {
        _availabilityChecked = false;
        _serverErrors.Remove(nameof(_model.PreferredDoctor));
        await LoadTimeSlotsAsync();
    }

    private async Task OnDateChangedAsync()
    {
        _availabilityChecked = false;
        _dateInPastError = _model.AppointmentDate.HasValue
            && _model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today);
        await LoadTimeSlotsAsync();
    }

    private async Task LoadTimeSlotsAsync()
    {
        _model.TimeSlot = "";
        _serverErrors.Remove(nameof(_model.TimeSlot));

        if (!string.IsNullOrEmpty(_model.PreferredDoctor) && _model.AppointmentDate.HasValue)
        {
            _timeSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(
                _model.PreferredDoctor, _model.AppointmentDate.Value);
        }
        else
        {
            _timeSlots = [];
        }
    }

    private async Task CheckAvailabilityAsync()
    {
        _serverErrors.Clear();
        _availabilityChecked = false;

        // Client-side date check
        if (_model.AppointmentDate.HasValue
            && _model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            _dateInPastError = true;
            return;
        }
        _dateInPastError = false;

        var result = await AppointmentSvc.ValidatePatientAsync(_model);

        if (!result.IsValid)
        {
            _serverErrors = result.Errors;
            return;
        }

        _availabilityChecked = true;
    }

    private async Task HandleSubmitAsync()
    {
        if (!_availabilityChecked)
            return;

        if (_model.AppointmentDate.HasValue
            && _model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            _dateInPastError = true;
            return;
        }

        // Re-validate server-side before final submission
        var result = await AppointmentSvc.ValidatePatientAsync(_model);
        if (!result.IsValid)
        {
            _serverErrors = result.Errors;
            _availabilityChecked = false;
            return;
        }

        _submitted = true;
    }
}

